119: export function detectPricedAddressConstants(stripped: string): Set<string> {
120:   const priced = new Set<string>();
121:   for (const re of [PRICED_CONFIG_FIELD, PRICED_USD_HELPER_ARG]) {
122:     let match: RegExpExecArray | null;
123:     re.lastIndex = 0;
124:     while ((match = re.exec(stripped)) !== null) {
125:       const ident = match[1]!;
126:       if (ident !== "address") priced.add(ident);
127:     }
128:   }
129:   return priced;
130: }
